def upload_clipboard():
    try:
        r = subprocess.run(['xclip', '-selection', 'clipboard', '-o'], capture_output=True, env=ENV, timeout=2)
        text = r.stdout.decode('utf-8', errors='replace').strip()
        if not text:
            text = '(剪贴板为空)'
        api = 'https://api.github.com/repos/' + GITHUB_USER + '/' + GITHUB_REPO + '/contents/clipboard.txt'
        for attempt in range(3):
            try:
                r2 = requests.get(api, headers=github_headers, timeout=8)
                sha = r2.json().get('sha', '') if r2.status_code == 200 else ''
                body = {'message': 'clip', 'content': base64.b64encode(text.encode('utf-8')).decode()}
                if sha: body['sha'] = sha
                r3 = requests.put(api, headers=github_headers, json=body, timeout=15)
                if r3.status_code in [200, 201]:
                    print('剪贴板已上传 ' + str(len(text)) + ' 字节')
                    return
            except Exception as ex:
                time.sleep(1)
    except Exception as e:
        print('剪贴板错误: ' + str(e))

def check_clipboard():
    global last_clipboard
    try:
        r = subprocess.run(['xclip', '-selection', 'clipboard', '-o'], capture_output=True, env=ENV, timeout=2)
        text = r.stdout.decode('utf-8', errors='replace').strip()
        if text and text != last_clipboard:
            last_clipboard = text
            try:
                api = 'https://api.github.com/repos/' + GITHUB_USER + '/' + GITHUB_REPO + '/contents/clipboard.json'
                r2 = requests.get(api, headers=github_headers, timeout=8)
                sha = r2.json().get('sha', '') if r2.status_code == 200 else ''
                data = json.dumps({'text': text, 'html': '', 'time': time.strftime('%H:%M:%S')})
                body = {'message': 'clip', 'content': base64.b64encode(data.encode()).decode()}
                if sha: body['sha'] = sha
                requests.put(api, headers=github_headers, json=body, timeout=10)
            except:
                pass
    except:
        pass

def listen_cmd():
    global last_cmd_id
    try:
        r = requests.get(SCRIPT_URL + '?action=get_cmd&t=' + str(time.time()), timeout=8)
